UPDATE kayit SET notu = 55 WHERE ogr_no = 1002 AND ders_kodu = 'BIL3005';

SELECT log_id, ogr_no, ders_kodu, eski_not, yeni_not
FROM not_log
ORDER BY log_id;

CREATE VIEW v_bil AS
SELECT ogr_no, ad, soyad, sinif FROM ogrenci WHERE bolum_id = 1;

CREATE TRIGGER trg_v_bil_upd
INSTEAD OF UPDATE ON v_bil
FOR EACH ROW
BEGIN
    UPDATE ogrenci SET sinif = NEW.sinif WHERE ogr_no = OLD.ogr_no;
END;

UPDATE v_bil SET sinif = 4 WHERE ogr_no = 1003;

SELECT ogr_no, ad, sinif FROM v_bil ORDER BY ogr_no;

questions.explain:
`SAVEPOINT ad` ile işlem içinde bir ara nokta işaretlenir; `ROLLBACK TO SAVEPOINT ad` yalnızca o noktadan sonraki değişiklikleri geri alır ve işlem **açık kalır**, sonra `COMMIT` ile kalan kısım kalıcılaşır.

```sql
BEGIN;
  UPDATE ogrenci SET burs_orani = 50 WHERE ogr_no = 1002;
  SAVEPOINT sp_burs;
  UPDATE ogrenci SET burs_orani = 200 WHERE ogr_no = 1002;
  ROLLBACK TO sp_burs;
COMMIT;
```
Çıktı: `SELECT ogr_no, burs_orani FROM ogrenci WHERE ogr_no = 1002;` $\rightarrow$ `1002|50`. Düz `ROLLBACK` olsaydı ilk UPDATE de gidecek ve sonuç `1002|NULL` olacaktı.

