BEGIN;
  UPDATE ogrenci SET burs_orani = 60 WHERE ogr_no = 1001;
COMMIT;

-- T2: kurban secildi, tamami geri alinir
BEGIN;
  UPDATE ogrenci SET burs_orani = 90 WHERE ogr_no = 1003;
  UPDATE ogrenci SET burs_orani = 10 WHERE ogr_no = 1001;
