-- T1: commit eder -> REDO listesine girecek tur is
BEGIN;
  UPDATE kayit SET notu = 100 WHERE ogr_no = 1007 AND ders_kodu = 'MAK1001';
COMMIT;

-- T2: kismi geri alma yapip commit eder
BEGIN;
  UPDATE kayit SET notu = 55 WHERE ogr_no = 1006 AND ders_kodu = 'EEM2001';
  SAVEPOINT sp1;
  UPDATE kayit SET notu = 0 WHERE ders_kodu = 'EEM2001';
  ROLLBACK TO sp1;
COMMIT;

-- T3: cokme anina denk geldi -> UNDO listesine girecek tur is
BEGIN;
  UPDATE kayit SET notu = 1 WHERE ders_kodu IN ('MAK1001', 'EEM2001');
ROLLBACK;

